# This code has been fully generated by an AI.
"""Hebocon-Client: findet den Server im LAN, meldet sich mit Namen an und öffnet die passenden Fenster.

Der Client hat kein eigenes Spiel. Er liefert nur die Seiten aus web/ lokal aus; Zustand, Aktionen und
Medien kommen vom Server. Mit dem Namen „KI“ fährt stattdessen ein Copilot-Modell (pilot.py).
"""

import argparse
import functools
import getpass
import json
import os
import socket
import sys
import threading
import time
import urllib.error
import urllib.parse
import urllib.request
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

ROOT = Path(__file__).resolve().parent
WEB = ROOT / "web"
CONFIG = ROOT / "client.json"
DEFAULT_PORT = 8765
DISCOVERY_PORT = 8766
MAGIC = b"HEBOCON?"
# Mit diesem Namen wird der PC zum KI-Spieler (siehe pilot.py) statt Fenster zu öffnen.
AI_NAMES = ("ai", "ki")


# ---------- Einstellungen ----------

def load_config() -> dict:
    try:
        return json.loads(CONFIG.read_text("utf-8"))
    except (OSError, ValueError):
        return {}


def save_config(cfg: dict) -> None:
    try:
        CONFIG.write_text(json.dumps(cfg, ensure_ascii=False, indent=1), "utf-8")
    except OSError as exc:
        print(f"Hinweis: {CONFIG.name} ließ sich nicht speichern ({exc}).")


# ---------- Server finden ----------

def http_json(server: str, path: str, data: dict | None = None, token: str = "",
              timeout: float = 3.0) -> dict:
    body = json.dumps(data).encode() if data is not None else None
    req = urllib.request.Request(f"http://{server}{path}", data=body, method="POST" if body else "GET")
    req.add_header("Content-Type", "application/json")
    if token:
        req.add_header("Authorization", f"Bearer {token}")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as res:
            return json.loads(res.read())
    except urllib.error.HTTPError as exc:
        # Ablehnungen (400/403) tragen eine Klartext-Meldung, die der Nutzer sehen soll.
        try:
            return json.loads(exc.read())
        except ValueError:
            return {"ok": False, "message": f"Server antwortet mit Fehler {exc.code}."}


def hello(server: str) -> dict | None:
    try:
        info = http_json(server, "/lobby/hello", timeout=2.0)
    except (OSError, ValueError):
        return None
    return info if info.get("app") == "hebocon" else None


def broadcast_targets() -> list[str]:
    targets = ["255.255.255.255", "127.0.0.1"]
    try:
        # Windows leitet 255.255.255.255 nur über eine Netzwerkkarte; die Netz-Broadcasts erreichen alle.
        for info in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET):
            a, b, c, _ = info[4][0].split(".")
            targets.append(f"{a}.{b}.{c}.255")
    except OSError:
        pass
    return list(dict.fromkeys(targets))


def discover(seconds: float = 2.0) -> list[tuple[str, str]]:
    """Antwortende Server als (adresse:port, server_id)."""
    found: dict[str, str] = {}
    with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
        sock.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
        sock.settimeout(0.3)
        for target in broadcast_targets():
            try:
                sock.sendto(MAGIC, (target, DISCOVERY_PORT))
            except OSError:
                continue
        end = time.monotonic() + seconds
        while time.monotonic() < end:
            try:
                data, addr = sock.recvfrom(512)
            except TimeoutError:
                continue
            except OSError:
                continue
            try:
                info = json.loads(data)
            except ValueError:
                continue
            if info.get("app") == "hebocon":
                found.setdefault(f"{info.get('ip') or addr[0]}:{info.get('port', DEFAULT_PORT)}",
                                 str(info.get("id", "")))
    # Ältere Server ohne "ip" antworten über mehrere Wege; die LAN-Adresse taugt auch für andere.
    unique: dict[str, str] = {}
    for server, sid in sorted(found.items(), key=lambda x: x[0].startswith("127.")):
        if sid not in unique:
            unique[sid] = server
    return [(server, sid) for sid, server in unique.items()]


def normalize(text: str) -> str:
    text = text.strip().removeprefix("http://").rstrip("/")
    return text if ":" in text else f"{text}:{DEFAULT_PORT}"


def find_server(cfg: dict, forced: str | None) -> tuple[str, str]:
    if forced:
        server = normalize(forced)
        info = hello(server)
        if info:
            return server, info["id"]
        print(f"Server {server} antwortet nicht.")
    else:
        print("Suche Hebocon-Server im LAN …")
        found = discover()
        last = cfg.get("server")
        if found:
            # Mehrere Server: den zuletzt benutzten nehmen, sonst den ersten.
            for server, sid in found:
                if server == last or sid == cfg.get("server_id"):
                    return server, sid
            if len(found) > 1:
                print("Mehrere Server gefunden: " + ", ".join(s for s, _ in found))
            return found[0]
        if last:
            info = hello(last)
            if info:
                print(f"Automatische Suche erfolglos, nehme den zuletzt benutzten Server {last}.")
                return last, info["id"]
        print("Kein Server gefunden. Läuft hebo-server\\start.bat? Blockiert die Firewall UDP "
              f"{DISCOVERY_PORT} oder TCP {DEFAULT_PORT}?")
    while True:
        default = cfg.get("server", "")
        hint = f" [{default}]" if default else ""
        text = input(f"Server-IP{hint}: ").strip() or default
        if not text:
            continue
        server = normalize(text)
        info = hello(server)
        if info:
            return server, info["id"]
        print(f"Unter {server} antwortet kein Hebocon-Server. Adresse und Firewall prüfen.")


# ---------- Anmelden ----------

def login(server: str, server_id: str, cfg: dict) -> dict:
    tokens = cfg.setdefault("tokens", {}).setdefault(server_id, {})
    ai = None
    while True:
        name = input("name: ").strip()
        if not name:
            continue
        key = name.lower()
        role_key = "moderator" if key in ("mod", "moderator") else key
        data = {"name": name, "token": tokens.get(role_key, "")}
        if role_key == "moderator":
            data["password"] = getpass.getpass("Passwort: ")
        elif key in AI_NAMES:
            # Erst einrichten: der Server zeigt das gewählte Modell als Spielernamen.
            import pilot

            try:
                ai = ai or pilot.setup(cfg)
            except pilot.PilotError as exc:
                print(exc)
                continue
            save_config(cfg)
            role_key = "ki"
            data = {"name": "KI", "token": tokens.get(role_key, ""), "model": ai.label}
        try:
            result = http_json(server, "/lobby/join", data)
        except (OSError, ValueError):
            print("Server nicht erreichbar. Läuft er noch?")
            continue
        if result.get("ok"):
            tokens[role_key] = result["token"]
            if result.get("ai"):
                result["pilot"] = ai
            return result
        print(result.get("message", "Anmeldung abgelehnt."))
        if result.get("code") != "full" or key in AI_NAMES:
            continue
        if input("Stattdessen als Bühne verbinden? (j/n) ").strip().lower() == "j":
            result = http_json(server, "/lobby/join", {"name": "stage", "token": tokens.get("stage", "")})
            if result.get("ok"):
                tokens["stage"] = result["token"]
                return result
            print(result.get("message", "Anmeldung abgelehnt."))


# ---------- Seiten ausliefern ----------

class Handler(SimpleHTTPRequestHandler):
    extensions_map = {**SimpleHTTPRequestHandler.extensions_map, ".js": "text/javascript"}

    def end_headers(self):
        # Nach einem Update sollen alle Geräte sofort die neuen Seiten laden, nicht einen alten Stand.
        self.send_header("Cache-Control", "no-store")
        super().end_headers()

    def log_message(self, format, *args):
        pass


def serve_web() -> int:
    httpd = ThreadingHTTPServer(("127.0.0.1", 0), functools.partial(Handler, directory=str(WEB)))
    threading.Thread(target=httpd.serve_forever, name="web", daemon=True).start()
    return httpd.server_address[1]


def watch(server: str, stop: threading.Event) -> None:
    online = True
    while not stop.wait(5):
        now = hello(server) is not None
        if now != online:
            print(f"Verbindung zum Server {server} wieder da." if now
                  else f"Verbindung zum Server {server} verloren, versuche weiter …")
            online = now


# ---------- Start ----------

def run_ai(server: str, result: dict) -> None:
    import pilot

    print(f"Angemeldet als KI-Spieler {result['slot']}: {result['name']}")
    try:
        pilot.run(server, result, result["pilot"])
    except pilot.PilotError as exc:
        print(exc)
    except KeyboardInterrupt:
        print("KI beendet, Roboter angehalten.")
    finally:
        try:
            http_json(server, "/lobby/leave", {}, token=result["token"], timeout=2.0)
            print("Spielerplatz freigegeben.")
        except (OSError, ValueError):
            pass


def main() -> None:
    parser = argparse.ArgumentParser(prog="hebo-client")
    parser.add_argument("--server", help="Server-Adresse (IP oder IP:Port) statt automatischer Suche")
    args = parser.parse_args()

    cfg = load_config()
    server, server_id = find_server(cfg, args.server)
    print(f"Verbunden mit Hebocon-Server {server}.")
    cfg["server"] = server
    cfg["server_id"] = server_id
    save_config(cfg)

    result = login(server, server_id, cfg)
    save_config(cfg)
    role = result["role"]
    if result.get("ai"):
        run_ai(server, result)
        return
    if role == "player":
        print(f"Angemeldet als Spieler {result['slot']}: {result['name']}")
    else:
        print(f"Angemeldet als {'Moderation' if role == 'moderator' else 'Bühne'}.")

    port = serve_web()
    query = urllib.parse.urlencode({"server": server, "token": result["token"], "role": role,
                                    "name": result["name"]})
    base = f"http://127.0.0.1:{port}"

    # Ohne Klick ins Bühnenfenster blockiert WebView2 sonst Memes mit Ton; die Overscroll-Option
    # setzt pywebview selbst und ginge durch die Variable verloren.
    os.environ.setdefault("WEBVIEW2_ADDITIONAL_BROWSER_ARGUMENTS",
                          "--disable-features=ElasticOverscroll --autoplay-policy=no-user-gesture-required")
    import webview

    webview.create_window(f"Hebocon Spieler – {result['name']}" if role == "player" else "Hebocon Bühne",
                          f"{base}/stage.html?{query}", width=1280, height=760,
                          fullscreen=bool(cfg.get("stage_fullscreen", False)), background_color="#000000")
    if role == "moderator":
        webview.create_window("Hebocon Bedienung", f"{base}/operator.html?{query}", width=1300, height=900)

    stop = threading.Event()
    threading.Thread(target=watch, args=(server, stop), name="watch", daemon=True).start()
    print("Fenster offen. Zum Beenden alle Fenster schließen.")
    try:
        webview.start()
    finally:
        stop.set()
        if role == "player":
            try:
                http_json(server, "/lobby/leave", {}, token=result["token"], timeout=2.0)
                print("Spielerplatz freigegeben.")
            except (OSError, ValueError):
                pass


if __name__ == "__main__":
    try:
        main()
    except (KeyboardInterrupt, EOFError):
        sys.exit(0)
